def title_from_file(p):
    m=re.search(r'<title>(.*?) \| On A Trip Holidays', p.read_text(errors='ignore'), re.S)
    return m.group(1).strip() if m else p.stem.replace('package-','').replace('-',' ').title()

def block(key, title):
    d=DATA.get(key, dict(best='Ask our travel team',fit='Families • Couples • Friends',pace='Moderate',walk='Moderate',weather='Variable',food='Veg & local options',exp=['Local highlights','Scenic experiences','Curated sightseeing','Flexible free time']))
    exp=''.join(f'<div class="intel-exp"><span>✦</span><b>{html.escape(x)}</b><small>Recommended experience</small></div>' for x in d['exp'])
    return f'''<section class="trip-intelligence" id="smart-plan">
      <div class="intel-head"><div><div class="eyebrow">ON A TRIP SMART PLAN</div><h2>Know before you book</h2><p>Useful trip intelligence so you can understand the pace, comfort level and highlights before confirming your holiday.</p></div><a class="intel-tool" href="smart-plan.html">🧠 Check any itinerary</a></div>
      <div class="intel-facts"><div><small>BEST TIME</small><b>{html.escape(d['best'])}</b></div><div><small>BEST FOR</small><b>{html.escape(d['fit'])}</b></div><div><small>TRIP PACE</small><b>{html.escape(d['pace'])}</b></div><div><small>WALKING</small><b>{html.escape(d['walk'])}</b></div><div><small>WEATHER</small><b>{html.escape(d['weather'])}</b></div><div><small>FOOD</small><b>{html.escape(d['food'])}</b></div></div>
      <div class="intel-grid"><div class="intel-card"><div class="eyebrow">DON'T MISS</div><h3>Signature experiences</h3><div class="intel-exps">{exp}</div></div><div class="intel-card before-book"><div class="eyebrow">BEFORE YOU BOOK</div><h3>What to keep in mind</h3><ul><li>✓ Route and drive times are indicative and may change.</li><li>✓ Final hotels, vehicle and meal plan are confirmed on the booking voucher.</li><li>✓ Weather, permits and local rules can affect sightseeing.</li><li>✓ Ask us for a private, family, senior-friendly or customised version.</li></ul><a class="btn" href="contact.html?package={key}">Plan My Trip</a></div></div>
    </section>'''

for p in root.glob('package-*.html'):
    key=p.stem.replace('package-','')
    text=p.read_text(errors='ignore')
    if 'trip-intelligence' in text: continue
    marker='<div class="v29-tabs">'
    text=text.replace(marker, block(key,title_from_file(p))+marker,1)
    p.write_text(text)

