smart='''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>On A Trip Smart Plan | Itinerary Check</title><meta name="description" content="Check your travel itinerary for pace, long drives, gaps and practical planning points with On A Trip Smart Plan."><link rel="stylesheet" href="style.css"></head><body><nav class="nav"><a class="brand" href="index.html"><img alt="On A Trip Holidays" src="assets/logo.png"></a><div class="navlinks"><a href="packages.html">Packages</a><a href="pilgrimage.html">Pilgrimage</a><a href="packages.html#batches">Batches</a><a href="blogs.html">Blogs</a><a href="about.html">About</a><a href="contact.html">Contact</a></div><a class="wa" href="https://wa.me/919182894146?text=Hi%20On%20A%20Trip%20Holidays%2C%20I%20want%20to%20check%20my%20itinerary">WhatsApp Us</a></nav><main class="smart-page"><section class="smart-hero"><div class="eyebrow">ON A TRIP SMART PLAN</div><h1>Is your itinerary actually a good plan?</h1><p>Paste your itinerary below and get an instant planning check for pace, long travel days, missing details and practical trip questions.</p><div class="smart-note">This is a quick planning assistant — not a substitute for local conditions, permits or professional travel advice.</div></section><section class="smart-tool"><div class="smart-input"><label for="plan">Paste your itinerary</label><textarea id="plan" placeholder="Example: Day 1 Leh arrival... Day 2 Leh local... Day 3 Nubra..."></textarea><div class="smart-actions"><button class="btn" onclick="analysePlan()">Check My Plan</button><a class="btn light" href="contact.html">Ask Our Planner</a></div></div><div id="result" class="smart-result"><div class="smart-placeholder"><span>🧭</span><h2>Your trip score will appear here</h2><p>We’ll look for pacing, repeated routes, long-drive signals, missing stays/meals and practical details.</p></div></div></section><section class="smart-grid"><article><span>⏱</span><h3>Pace Check</h3><p>Flags itineraries that appear overloaded or leave too little time for a destination.</p></article><article><span>🚗</span><h3>Route Check</h3><p>Looks for long-drive and repeated-route signals that deserve a second look.</p></article><article><span>🏨</span><h3>Booking Gaps</h3><p>Highlights missing hotel, meal, pickup or activity details.</p></article><article><span>💬</span><h3>Human Review</h3><p>Send the plan to our travel team when you want a customised expert review.</p></article></section></main><footer><div><div class="footlogo"><img alt="On A Trip Holidays" src="assets/logo.png"></div><p>Trusted travel company for Telangana & Andhra Pradesh — Telugu-first support for pilgrimage, domestic, adventure and international holidays.</p></div><div><h4>Explore</h4><a href="packages.html">All Packages</a><a href="pilgrimage.html">Pilgrimage</a><a href="blogs.html">Travel Blog</a></div><div><h4>Popular</h4><a href="package-ladakh.html">Ladakh</a><a href="package-char-dham.html">Char Dham</a><a href="package-kashmir.html">Kashmir</a><a href="package-thailand.html">Thailand</a></div><div class="copy">© 2026 On A Trip Holidays. All rights reserved.</div></footer><script>function analysePlan(){const t=document.getElementById('plan').value.trim();const r=document.getElementById('result');if(!t){r.innerHTML='<div class="smart-placeholder"><span>✍️</span><h2>Paste your itinerary first</h2><p>Add the day-wise plan and run the check.</p></div>';return}const days=(t.match(/day\s*\d+/gi)||[]).length;const long=(t.match(/\b(8|9|10|11|12|13|14|15)\s*(hours?|hrs?)\b/gi)||[]).length;const drive=(t.match(/drive|transfer|road|km|distance/gi)||[]).length;const gaps=[];if(days<2)gaps.push('Add a clear day-wise sequence.');if(long)gaps.push('Review long-drive days and add realistic buffers.');if(!/hotel|stay|resort|camp|homestay/i.test(t))gaps.push('Accommodation details are missing.');if(!/meal|breakfast|dinner|lunch/i.test(t))gaps.push('Meal information is missing.');if(!/pickup|drop|airport|station/i.test(t))gaps.push('Pickup / drop details are missing.');if(!/permit|weather|condition|altitude|insurance/i.test(t))gaps.push('Add destination-specific practical notes.');let score=100-(days<2?15:0)-(long*5)-(gaps.length*5);score=Math.max(55,Math.min(98,score));const verdict=score>=85?'Looks well structured':score>=70?'Good base — a few details need attention':'Needs a planning review';r.innerHTML='<div class="score"><div class="score-circle">'+score+'<small>/100</small></div><div><div class="eyebrow">SMART PLAN VERDICT</div><h2>'+verdict+'</h2><p>Quick automated check based on the text you provided.</p></div></div><div class="check-list">'+(gaps.length?gaps.map(x=>'<div>⚠️ '+x+'</div>').join(''):'<div>✓ No obvious planning gaps found in this quick check.</div>')+'</div><a class="btn" href="contact.html?subject=Itinerary%20Review">Get Human Review</a>'}</script></body></html>'''
